			table1_r5c1: "تقسيم إيردري (الحد الأدنى القانوني: 2)",
			table1_r5c2: "قطعتان (2)",
			table1_r5c3: "4 بحسب الأرض؛ 3 بحسب السكان (≥2%)",
			table1_r6c1: "<strong>الملخص الهيكلي المسجَّل مسبقاً</strong> (4 من 5 أو أكثر = خريطة شاذة)",
			table1_r6c2: "<strong>0 من 5</strong>",
